<?php
declare(strict_types=1);namespace App\Http\Controllers\Hrd;use App\Http\Controllers\Controller;use App\Models\{PersonnelAttendance,PersonnelCashAdvance,PersonnelLeaveRequest,PersonnelPayroll};use Illuminate\Http\Request;use Illuminate\View\View;
class HrdReportController extends Controller{public function index(Request$r):View{$start=$r->date('start_date')??now()->startOfMonth();$end=$r->date('end_date')??now()->endOfMonth();$attendance=PersonnelAttendance::with('personnel')->whereBetween('attendance_date',[$start,$end]);$payroll=PersonnelPayroll::whereBetween('period_start',[$start,$end]);$leaves=PersonnelLeaveRequest::whereBetween('start_date',[$start,$end]);$advances=PersonnelCashAdvance::whereBetween('request_date',[$start,$end]);return view('hrd.reports.index',['title'=>'Laporan HRD','start'=>$start,'end'=>$end,'attendances'=>(clone$attendance)->paginate(20),'attendanceSummary'=>(clone$attendance)->selectRaw('status,count(*) total')->groupBy('status')->pluck('total','status'),'minutes'=>(clone$attendance)->selectRaw('sum(late_minutes) late,sum(overtime_minutes) overtime')->first(),'payrollSummary'=>(clone$payroll)->selectRaw('count(*) employees,sum(base_salary) base,sum(allowance) allowance,sum(deduction+late_deduction+cash_advance_deduction) deductions,sum(cash_advance_deduction) cash_advance,sum(total) net')->first(),'leaveSummary'=>(clone$leaves)->selectRaw('leave_type,count(*) total')->groupBy('leave_type')->pluck('total','leave_type'),'advanceSummary'=>(clone$advances)->selectRaw('sum(case when status in (\'disbursed\',\'partially_paid\',\'paid\') then amount else 0 end) disbursed,sum(amount-remaining_amount) paid,sum(remaining_amount) remaining')->first()]);}}
